local a=require("ExcelTool")local b=a.Pack;local c=a.Sub;local d=a.LangGet;local e=a.Dmap;local f=require("Excels.Data.item_definition.skin")local g=f.tb;local h=f.get;g[402906]=b({e[12057],402906,12,90,178,"「ドレスコードじゃと！？わらわは神様じゃぞ、俗世のルールに縛られる謂れなどないわ！ぐひひ、そうじゃ、今夜は一晩中、わらわの傍におれ。礼儀が大切と言うのなら、神様にも謹んで仕えるべきじゃからのう！」",200029,2,"deco/character/huiyeji_LF",false,false,1,"huiyeji_lf"},h)g[402907]=b({e[12045],402907,20,91,179,"「こっち、こっちじゃ！\nぼけ～っとしおって。わらわ直々に写真に納めてやったわ。\nせっかくのデートじゃというに、凡人ごときが神様であるこのわらわを待たせるなど……罰が当たっても知らぬぞ。\nまぁ、汝が誠心誠意わらわの身を揉み解し、その後わらわの美しい姿を撮ると言うなら、許してやっても構わぬがのう……ぐひひ。」",200029,2,"deco/character/huiyeji_yh",false,false,1,1,3627,5000,1933,3561,8000,9666,8633,8333,13000,8000,8000,"huiyeji_yh"},h)g[403001]=b({e[46059],403001,false,92,180,false,200030,false,"deco/character/403001",302002,60,false,false,false,false,-138,false,false,false,false,false,false,false,false,"0,350,0.94","-100,-20,1","-50,-20,1",false,false,false,"-120,0,1","-80,0,1",false,false,false,1916,801,400,1640,715,998,2997,1640,715,998,1046,0},h)g[403002]=b({e[12034],403002,1,4,181,"「なんです。いつから人の着替えを覗く趣味を持つようになったんですか。\nそこまでして『問題児リスト』に載りたいんですか？」",200030,1,"deco/character/403002",302002,60,1,1891,805,400,778,733,2354,3040,778,733,2354,1032,false,false,false,false,false,false,false,false,false,false,false,false,false,false,0},h)g[403003]=b({e[21034],403003,3,17,182,"「ここは立ち入り禁止にしていたはずですよ。今引き返せば見なかったことにしましょう。それとも……私に捕まえられたいのですか？」",200030,2,"deco/character/403003",false,false,false,false,false,false,false,"1",false,false,false,"0,140,0.88",1793,813,412,469,663,3389,3468,713,663,2901,1116,false,false,false,false,false,false,false,false,false,false,false,false,false,false,0},h)g[403004]=b({e[24034],403004,5,93,183,"「今回滞在する旅館は、そば打ちの名人なんです。近くには商店街もあって、珍しい食べ物もたくさんあるとか。……い、いえ、せっかく旅行に行くんですから事前にきっちり調べておこうと思っただけで、決して食べたいわけでは……。」",200030,2,"deco/character/403004",false,false,1,false,1,false,false,"1",false,false,"-50,0,1","170,40,0.9","-100,0,1","-100,0,1","-120,0,1",2012,887,390,168,118,3409,3424,422,581,2901,1261,1,4813,5000,4097,5319,6666,6333,7000,8333,14000,8000,6666,false,false,0},h)g[403101]=b({e[46057],403101,false,94,184,false,200031,false,"deco/character/403101",302002,60,false,false,false,false,-215,"1",false,false,false,false,false,false,false,"0,380,0.94","-100,-20,1","-50,0,1",false,false,false,"-110,0,1","-40,0,1",false,false,false,1908,798,400,1274,649,1438,3140,1274,649,1438,1109,"shiyuanduihai",false,0},h)g[403102]=b({e[12034],403102,1,4,185,"「君ももう部員なんだから、試食専門って訳にはいかないよ！\nさっさと手伝わないと、今週はおやつ抜きにしちゃおっかな～？」",200031,1,"deco/character/403102",302002,60,1,1884,854,400,1564,768,1253,2864,1564,768,1253,1046,false,false,false,false,false,false,false,false,false,false,false,false,"shiyuanduihai_0",false,0},h)g[403103]=b({e[12034],403103,4,95,186,"「クリスマスの定番と言えば、雪降る夜にサンタクロースを待つ、って感じ？　でも俺は君と一緒に、エテルニテのフォレノワールを食べに行きたいけど……なんでって、クリスマスは親しい人と幸せを分け合うものだろ？」",200031,2,"deco/character/403103",false,false,1,1832,801,400,1010,448,2263,3444,1010,500,2263,1261,false,false,false,false,false,false,false,false,false,false,false,false,"shiyuanduihai_sd",false,0},h)g[403104]=b({e[21034],403104,2,18,187,"「ひゃっほーう！　やっぱ夏といったら海とかき氷！　もちろん君と一緒にいることもマストだね。それより知ってた？　バニラアイスにチョコソースをかけてクッキークランチをトッピングすれば、いつもの2倍美味しいよ！」",200031,2,"deco/character/403104",false,false,false,false,false,false,false,"1",false,false,false,"0,-140,1",1932,866,396,760,561,2895,2354,760,563,2895,1261,false,false,false,false,false,false,false,false,false,false,false,false,"shiyuanduihai_xr",false,0},h)g[403105]=b({e[9057],403105,22,96,188,"「いかなる時でも、心がスイーツを求める限り、おとぎの国のお茶会は、いつでも君をお招きするよ。\nあらゆる悩みと疲れを消し去る、特製魔法スイーツをお望みなら、俺の名前を呼んで。」",200031,2,"deco/character/403105","shiyuanduihai_hxsw",false,0},h)g[403201]=b({e[46057],403201,false,97,189,false,200032,false,"deco/character/ailisha",302002,60,false,false,false,false,118,"0.949999988079071",false,false,false,false,false,false,false,"60,190,0.97","0,100,0.95","0,70,0.95","0,0,0.95","0,0,0.95","0,0,0.95","0,80,0.95","0,80,0.95","0,0,0.95",false,false,1888,968,422,1173,840,1735,2664,1173,840,1735,1099,"